import {
  type PortableLearnerData,
  type UiAnswer,
  type UiAction,
  type UiDocument,
  type UiDocumentNode,
  type UiStudyPlanItem,
} from "@keating/learner-contracts";
import { createDeckWithCards } from "./learner-decks";
import { recordCardReview } from "./learner-mutations";
import type { UiActionMutationResult } from "./learner-repository";

function shortHash(value: string): string {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function stableId(prefix: string, ...parts: string[]): string {
  return `${prefix}-${shortHash(parts.join(":"))}`;
}

function actionTarget(document: UiDocument, nodeId: string): { node: UiDocumentNode; questionPrompt?: string } {
  for (const node of document.nodes) {
    if (node.id === nodeId) return { node, questionPrompt: node.type === "question" ? node.prompt : undefined };
    if (node.type === "quiz") {
      const question = node.questions.find((candidate) => candidate.id === nodeId);
      if (question) return { node, questionPrompt: question.prompt };
    }
  }
  throw new Error(`OpenUI action target ${nodeId} is missing.`);
}

function nextDocument(
  source: UiDocument,
  now: string,
  update: (nodes: UiDocumentNode[]) => UiDocumentNode[] = (nodes) => nodes,
  lifecycle: UiDocument["lifecycle"] = "ready",
): UiDocument {
  return {
    ...source,
    revision: source.revision + 1,
    lifecycle,
    nodes: update(structuredClone(source.nodes)),
    updatedAt: now,
  };
}

function answerText(action: Extract<UiAction, { type: "submit-answer" | "choose-option" }>, document: UiDocument): string {
  if (action.type === "submit-answer") return serializeAnswer(action.answer);
  const target = actionTarget(document, action.nodeId);
  const question = target.node.type === "question"
    ? target.node
    : target.node.type === "quiz"
      ? target.node.questions.find((candidate) => candidate.id === action.nodeId)
      : undefined;
  const labels = new Map(question?.choices?.map((choice) => [choice.id, choice.label]) ?? []);
  return action.optionIds.map((id) => labels.get(id) ?? id).join(", ");
}

function serializeAnswer(answer: UiAnswer): string {
  if (typeof answer === "string") return answer;
  if (answer.every((entry) => typeof entry === "string")) return answer.join(", ");
  return JSON.stringify(answer);
}

function updatePlanItem(items: readonly UiStudyPlanItem[], itemId: string, completed: boolean): UiStudyPlanItem[] {
  return items.map((item) => ({
    ...item,
    ...(item.id === itemId ? { status: completed ? "done" as const : "not_started" as const } : {}),
    ...(item.children ? { children: updatePlanItem(item.children, itemId, completed) } : {}),
  }));
}

function upsertArtifact(current: PortableLearnerData, artifact: PortableLearnerData["artifacts"][number]): PortableLearnerData {
  const exists = current.artifacts.some((candidate) => candidate.id === artifact.id);
  return {
    ...current,
    artifacts: exists
      ? current.artifacts.map((candidate) => candidate.id === artifact.id ? artifact : candidate)
      : [...current.artifacts, artifact],
  };
}

/** Pure semantic adapter used inside UiActionStore's exclusive transaction. */
export function applyLocalUiAction(
  current: PortableLearnerData,
  action: UiAction,
  document: UiDocument,
  now: string,
  sessionId?: string,
): UiActionMutationResult {
  if (action.type === "submit-answer" || action.type === "choose-option") {
    const target = actionTarget(document, action.nodeId);
    const answer = answerText(action, document);
    const check = {
      id: stableId("ui-answer", document.id, action.idempotencyKey),
      topic: target.node.type === "quiz" ? target.node.title : "Interactive check",
      question: target.questionPrompt ?? "OpenUI question",
      answer,
      createdAt: now,
      grading: "pending" as const,
      ...(sessionId ? { sessionId } : {}),
    };
    const next = current.questionChecks.some((candidate) => candidate.id === check.id)
      ? current
      : { ...current, questionChecks: [...current.questionChecks, check] };
    return {
      data: next,
      // Per-question completion lives in the durable action journal. Keeping
      // the document ready prevents one answer from disabling sibling nodes.
      resultingDocument: nextDocument(document, now),
      message: "Answer saved on this device.",
    };
  }

  if (action.type === "complete-goal-step") {
    const target = actionTarget(document, action.nodeId);
    if (target.node.type !== "goal") throw new Error("Goal action target is invalid.");
    const goalId = stableId("ui-goal", document.id, target.node.id);
    const existing = current.goals.find((goal) => goal.id === goalId);
    const baseGoal = existing ?? {
      id: goalId,
      title: target.node.title,
      description: target.node.description ?? "",
      updatedAt: now,
      steps: target.node.steps.map((step) => ({
        id: stableId("ui-step", document.id, target.node.id, step.id),
        title: step.title,
        status: step.status,
        successCriteria: [...(step.successCriteria ?? [])],
      })),
    };
    const stepIndex = target.node.steps.findIndex((step) => step.id === action.stepId);
    if (stepIndex < 0) throw new Error("Goal step is missing.");
    const portableStepId = stableId("ui-step", document.id, target.node.id, action.stepId);
    const goal = {
      ...baseGoal,
      updatedAt: now,
      steps: baseGoal.steps.map((step) => step.id === portableStepId ? { ...step, status: "done" as const } : step),
    };
    const goals = existing
      ? current.goals.map((candidate) => candidate.id === goal.id ? goal : candidate)
      : [...current.goals, goal];
    const resultingDocument = nextDocument(document, now, (nodes) => nodes.map((node) => {
      if (node.type !== "goal" || node.id !== target.node.id) return node;
      const steps = node.steps.map((step) => step.id === action.stepId ? { ...step, status: "done" as const } : step);
      return { ...node, status: steps.every((step) => step.status === "done") ? "completed" as const : node.status, steps };
    }));
    return { data: { ...current, goals }, resultingDocument, message: "Goal progress saved." };
  }

  if (action.type === "complete-plan-item") {
    const target = actionTarget(document, action.nodeId);
    if (target.node.type !== "study-plan" || !target.node.items) throw new Error("Study-plan action target is invalid.");
    const items = updatePlanItem(target.node.items, action.itemId, action.completed);
    const updatedPlan = { ...target.node, items };
    const artifactId = stableId("ui-plan", document.id, target.node.id);
    const prior = current.artifacts.find((artifact) => artifact.id === artifactId);
    const artifact = {
      id: artifactId,
      kind: "study-plan" as const,
      format: "json" as const,
      title: target.node.title ?? "Study plan",
      createdAt: prior?.createdAt ?? now,
      updatedAt: now,
      content: JSON.stringify(updatedPlan),
      ...(sessionId ? { sourceSessionId: sessionId } : {}),
    };
    const resultingDocument = nextDocument(document, now, (nodes) => nodes.map((node) => node.id === target.node.id ? updatedPlan : node));
    return {
      data: upsertArtifact(current, artifact),
      resultingDocument,
      message: "Study-plan progress saved.",
    };
  }

  if (action.type === "update-notes") {
    const target = actionTarget(document, action.nodeId);
    if (target.node.type !== "notes") throw new Error("Notes action target is invalid.");
    const artifactId = stableId("ui-note", document.id, target.node.id);
    const prior = current.artifacts.find((artifact) => artifact.id === artifactId);
    const artifact = {
      id: artifactId,
      kind: "note" as const,
      format: "markdown" as const,
      title: target.node.title,
      createdAt: prior?.createdAt ?? now,
      updatedAt: now,
      content: action.value,
      ...(sessionId ? { sourceSessionId: sessionId } : {}),
    };
    const resultingDocument = nextDocument(document, now, (nodes) => nodes.map((node) => node.id === target.node.id && node.type === "notes"
      ? { ...node, value: action.value }
      : node));
    return {
      data: upsertArtifact(current, artifact),
      resultingDocument,
      message: "Notes saved.",
    };
  }

  if (action.type === "rate-card") {
    const target = actionTarget(document, action.nodeId);
    if (target.node.type !== "deck") throw new Error("Deck action target is invalid.");
    const deckId = stableId("ui-deck", document.id, target.node.id);
    const cards = target.node.cards.map((card) => ({
      id: stableId("ui-card", document.id, target.node.id, card.id),
      front: card.front,
      back: card.back,
      tags: [...(card.tags ?? [])],
    }));
    const withDeck = current.decks.some((deck) => deck.id === deckId)
      ? current
      : createDeckWithCards(current, { id: deckId, title: target.node.title, topic: target.node.topic, createdAt: now, cards });
    const cardId = stableId("ui-card", document.id, target.node.id, action.cardId);
    const reviewed = recordCardReview(
      withDeck,
      deckId,
      cardId,
      action.rating,
      stableId("ui-review", document.id, action.idempotencyKey),
      now,
      sessionId,
    );
    return {
      data: reviewed.data,
      resultingDocument: nextDocument(document, now),
      message: "Card rating saved and the review schedule was updated.",
    };
  }

  if (action.type === "save-artifact") {
    const target = actionTarget(document, action.nodeId);
    if (!(target.node.type === "study-plan" || target.node.type === "artifact"
      || target.node.type === "image" || target.node.type === "media")) {
      throw new Error("Artifact action target is invalid.");
    }
    const resource = target.node.resource;
    if (!resource) throw new Error("Structured study plans are saved through their progress controls.");
    const id = stableId("ui-artifact", document.id, target.node.id);
    const kind = target.node.type === "study-plan" ? "study-plan" as const
      : target.node.type === "image" ? "image" as const
        : target.node.type === "media" && target.node.kind === "animation" ? "animation" as const
          : target.node.type === "media" ? "document" as const : "other" as const;
    const format = resource.format === "markdown" ? "markdown" as const
      : target.node.type === "image" ? "image" as const
        : target.node.type === "media" && target.node.kind === "video" ? "video" as const
          : resource.format === "json" ? "json" as const : "text" as const;
    const artifact = {
      id,
      kind,
      format,
      title: resource.title,
      createdAt: now,
      updatedAt: now,
      content: resource.content ?? resource.uri ?? "",
      ...(sessionId ? { sourceSessionId: sessionId } : {}),
    };
    return {
      data: upsertArtifact(current, artifact),
      // The receipt marks this resource saved; sibling interactions must stay usable.
      resultingDocument: nextDocument(document, now),
      message: "Artifact saved to your library.",
    };
  }

  if (action.type === "retry") {
    return { data: current, resultingDocument: nextDocument(document, now), message: "Interaction is ready to try again." };
  }

  return {
    data: current,
    resultingDocument: nextDocument(document, now),
    message: "Handoff opened.",
  };
}

export function uiActionLearnerMessage(action: UiAction, document: UiDocument): string | null {
  if (action.type === "submit-answer" || action.type === "choose-option") {
    const target = actionTarget(document, action.nodeId);
    return `My answer to "${target.questionPrompt ?? "the check"}": ${answerText(action, document)}`;
  }
  if (action.type === "complete-goal-step") {
    const target = actionTarget(document, action.nodeId);
    const step = target.node.type === "goal" ? target.node.steps.find((candidate) => candidate.id === action.stepId) : undefined;
    return step ? `I completed the goal step: ${step.title}. What should I do next?` : null;
  }
  return null;
}
import type { UiAction, UiActionJournal, UiDocument } from "@keating/learner-contracts";

/** Return the newest durable document snapshot produced by a completed action. */
export function latestUiDocument(
  journal: UiActionJournal,
  source: UiDocument,
): UiDocument {
  const latest = [...journal.receipts]
    .reverse()
    .find((receipt) => receipt.state === "completed" && receipt.result?.resultingDocument)
    ?.result?.resultingDocument;
  return latest && latest.revision >= source.revision ? latest : source;
}

/** Completed actions are UI state: restoring them prevents a quiz from appearing unanswered. */
export function completedUiActions(journal: UiActionJournal): UiAction[] {
  return journal.receipts
    .filter((receipt) => receipt.state === "completed" && receipt.result?.status === "completed")
    .map((receipt) => receipt.action);
}

export function completedQuestionAction(
  actions: readonly UiAction[],
  questionId: string,
): Extract<UiAction, { type: "submit-answer" | "choose-option" }> | undefined {
  return [...actions].reverse().find((action): action is Extract<UiAction, { type: "submit-answer" | "choose-option" }> =>
    (action.type === "submit-answer" || action.type === "choose-option") && action.nodeId === questionId);
}

export function completedNodeAction(
  actions: readonly UiAction[],
  nodeId: string,
  type: "save-artifact" | "open-handoff",
): boolean {
  return actions.some((action) => action.type === type && action.nodeId === nodeId);
}

export function reviewedDeckCardIds(actions: readonly UiAction[], nodeId: string): ReadonlySet<string> {
  return new Set(actions.flatMap((action) => action.type === "rate-card" && action.nodeId === nodeId ? [action.cardId] : []));
}
import { describe, expect, test } from "bun:test";
import type { PortableLearnerData, UiAction, UiDocument } from "@keating/learner-contracts";
import { applyLocalUiAction, uiActionLearnerMessage } from "../src/lib/ui-action-mutations";

const AT = "2026-08-10T00:00:00.000Z";
const empty: PortableLearnerData = {
  generatedAt: AT, sessions: [], artifacts: [], goals: [], questionChecks: [], quizResults: [], decks: [], cardReviews: [],
  studyPriorities: [], feedbackEvents: [], usageEvents: [], topicEvidence: [], benchmarks: [], evolutions: [],
  learnerProfile: { topicsExplored: [], strengths: [], weaknesses: [], sessionsCount: 0 },
};

function document(nodes: UiDocument["nodes"]): UiDocument {
  return { schemaVersion: 1, id: "document-1", revision: 0, lifecycle: "ready", supportedSurfaces: ["mobile"], nodes, createdAt: AT, updatedAt: AT };
}

describe("native OpenUI semantic actions", () => {
  test("persists answers and produces a learner turn", () => {
    const source = document([{ type: "question", id: "question-1", prompt: "What changed?", choices: [{ id: "evidence", label: "The evidence" }] }]);
    const action: UiAction = { schemaVersion: 1, type: "choose-option", documentId: source.id, documentRevision: 0, nodeId: "question-1", optionIds: ["evidence"], idempotencyKey: "answer-1" };
    const result = applyLocalUiAction(empty, action, source, AT);
    expect(result.data.questionChecks[0]).toMatchObject({ answer: "The evidence" });
    expect(result.resultingDocument).toMatchObject({ revision: 1, lifecycle: "ready" });
    expect(uiActionLearnerMessage(action, source)).toContain("The evidence");
  });

  test("creates a due deck and records a card rating", () => {
    const source = document([{ type: "deck", id: "deck-node", title: "Bayes", topic: "Bayes", cards: [{ id: "card-1", front: "Prior?", back: "Belief before evidence" }] }]);
    const action: UiAction = { schemaVersion: 1, type: "rate-card", documentId: source.id, documentRevision: 0, nodeId: "deck-node", cardId: "card-1", rating: 2, idempotencyKey: "rating-1" };
    const result = applyLocalUiAction(empty, action, source, AT);
    expect(result.data.decks).toHaveLength(1);
    expect(result.data.cardReviews).toHaveLength(1);
    expect(result.data.cardReviews[0]?.sessionId).toBeUndefined();
    expect(result.data.decks[0]?.cards[0]?.srs.intervalDays).toBe(1);
  });

  test("updates goal nodes and saves resources", () => {
    const goalSource = document([{ type: "goal", id: "goal-node", title: "Learn", status: "active", steps: [{ id: "step-1", title: "Explain", status: "not_started" }] }]);
    const goalAction: UiAction = { schemaVersion: 1, type: "complete-goal-step", documentId: goalSource.id, documentRevision: 0, nodeId: "goal-node", stepId: "step-1", idempotencyKey: "goal-1" };
    const goalResult = applyLocalUiAction(empty, goalAction, goalSource, AT);
    expect(goalResult.data.goals[0]?.steps[0]?.status).toBe("done");
    expect(goalResult.resultingDocument.lifecycle).toBe("ready");

    const artifactSource = document([{ type: "artifact", id: "artifact-node", resource: { id: "resource-1", title: "Notes", format: "markdown", content: "# Bayes" } }]);
    const artifactAction: UiAction = { schemaVersion: 1, type: "save-artifact", documentId: artifactSource.id, documentRevision: 0, nodeId: "artifact-node", idempotencyKey: "save-1" };
    const artifactResult = applyLocalUiAction(empty, artifactAction, artifactSource, AT);
    expect(artifactResult.data.artifacts[0]).toMatchObject({ title: "Notes", format: "markdown" });
  });

  test("persists structured study-plan progress and notes without losing sibling nodes", () => {
    const source = document([
      { type: "study-plan", id: "plan-node", title: "Bayes plan", items: [{ id: "plan-foundation", title: "Build the model", status: "not_started", children: [{ id: "plan-retrieve", title: "Retrieve it", status: "not_started" }] }] },
      { type: "notes", id: "notes-node", title: "Learner notes", value: "Initial model" },
    ]);
    const planAction: UiAction = { schemaVersion: 1, type: "complete-plan-item", documentId: source.id, documentRevision: 0, nodeId: "plan-node", itemId: "plan-retrieve", completed: true, idempotencyKey: "plan-progress-1" };
    const afterPlan = applyLocalUiAction(empty, planAction, source, AT);
    expect(afterPlan.data.artifacts[0]).toMatchObject({ kind: "study-plan", format: "json", title: "Bayes plan" });
    const plan = afterPlan.resultingDocument.nodes[0];
    expect(plan?.type === "study-plan" ? plan.items?.[0]?.children?.[0]?.status : undefined).toBe("done");

    const notesAction: UiAction = { schemaVersion: 1, type: "update-notes", documentId: source.id, documentRevision: 1, nodeId: "notes-node", value: "Evidence updates belief.", idempotencyKey: "notes-update-1" };
    const afterNotes = applyLocalUiAction(afterPlan.data, notesAction, afterPlan.resultingDocument, AT);
    expect(afterNotes.data.artifacts).toHaveLength(2);
    expect(afterNotes.data.artifacts[1]).toMatchObject({ kind: "note", format: "markdown", content: "Evidence updates belief." });
    const notes = afterNotes.resultingDocument.nodes[1];
    expect(notes?.type === "notes" ? notes.value : undefined).toBe("Evidence updates belief.");
  });

  test("persists structured answer arrays for blanks and matching", () => {
    const source = document([{ type: "question", id: "question-matching", kind: "matching", prompt: "Match the terms.", items: ["prior", "posterior"], choices: [{ id: "before", label: "Before" }, { id: "after", label: "After" }] }]);
    const action: UiAction = { schemaVersion: 1, type: "submit-answer", documentId: source.id, documentRevision: 0, nodeId: "question-matching", answer: [{ item: "prior", optionId: "before" }, { item: "posterior", optionId: "after" }], idempotencyKey: "matching-answer-1" };
    const result = applyLocalUiAction(empty, action, source, AT);
    expect(JSON.parse(result.data.questionChecks[0]?.answer ?? "null")).toEqual(action.answer);
  });

  test("keeps sibling nodes interactive after a durable action", () => {
    const source = document([
      { type: "question", id: "question-1", prompt: "First?" },
      { type: "question", id: "question-2", prompt: "Second?" },
      { type: "artifact", id: "artifact-node", resource: { id: "resource-1", title: "Notes", format: "markdown", content: "# Notes" } },
    ]);
    const answer: UiAction = { schemaVersion: 1, type: "submit-answer", documentId: source.id, documentRevision: 0, nodeId: "question-1", answer: "One", idempotencyKey: "answer-first" };
    const afterAnswer = applyLocalUiAction(empty, answer, source, AT);
    expect(afterAnswer.resultingDocument.lifecycle).toBe("ready");
    const save: UiAction = { schemaVersion: 1, type: "save-artifact", documentId: source.id, documentRevision: 1, nodeId: "artifact-node", idempotencyKey: "save-notes" };
    const afterSave = applyLocalUiAction(afterAnswer.data, save, afterAnswer.resultingDocument, AT);
    expect(afterSave.resultingDocument.lifecycle).toBe("ready");
    expect(afterSave.resultingDocument.nodes.find((node) => node.id === "question-2")).toBeDefined();
  });
});
import { describe, expect, test } from "bun:test";
import type { UiActionJournal, UiDocument } from "@keating/learner-contracts";
import { completedNodeAction, completedQuestionAction, completedUiActions, latestUiDocument, reviewedDeckCardIds } from "../src/lib/ui-render-state";

const source: UiDocument = {
  schemaVersion: 1,
  id: "quiz-doc",
  revision: 0,
  lifecycle: "ready",
  supportedSurfaces: ["mobile"],
  nodes: [{ type: "question", id: "question-1", prompt: "Why?" }],
  createdAt: "2026-08-10T00:00:00.000Z",
  updatedAt: "2026-08-10T00:00:00.000Z",
};

function journal(state: "pending" | "completed" = "completed"): UiActionJournal {
  const action = {
    schemaVersion: 1 as const,
    type: "submit-answer" as const,
    documentId: source.id,
    documentRevision: 0,
    nodeId: "question-1",
    answer: "Because the evidence changed.",
    idempotencyKey: "answer-1",
  };
  return {
    kind: "keating-ui-action-journal",
    schemaVersion: 1,
    documentId: source.id,
    receipts: [{
      schemaVersion: 1,
      action,
      actionFingerprint: "fingerprint",
      state,
      createdAt: source.createdAt,
      updatedAt: "2026-08-10T00:01:00.000Z",
      ...(state === "completed" ? { result: {
        schemaVersion: 1 as const,
        documentId: source.id,
        sourceRevision: 0,
        actionIdempotencyKey: action.idempotencyKey,
        status: "completed" as const,
        documentLifecycle: "completed" as const,
        resultingDocument: { ...source, revision: 1, lifecycle: "completed" as const, updatedAt: "2026-08-10T00:01:00.000Z" },
      } } : {}),
    }],
  };
}

describe("OpenUI durable render state", () => {
  test("restores the newest completed document and submitted answer", () => {
    const stored = journal();
    expect(latestUiDocument(stored, source).revision).toBe(1);
    const actions = completedUiActions(stored);
    expect(actions).toHaveLength(1);
    expect(completedQuestionAction(actions, "question-1")).toMatchObject({ answer: "Because the evidence changed." });
  });

  test("does not expose pending action state as completed UI", () => {
    const stored = journal("pending");
    expect(latestUiDocument(stored, source)).toEqual(source);
    expect(completedUiActions(stored)).toEqual([]);
  });

  test("projects saved resources and reviewed deck cards from durable actions", () => {
    const actions = [
      { schemaVersion: 1 as const, type: "save-artifact" as const, documentId: source.id, documentRevision: 1, nodeId: "artifact-1", idempotencyKey: "save-1" },
      { schemaVersion: 1 as const, type: "rate-card" as const, documentId: source.id, documentRevision: 2, nodeId: "deck-1", cardId: "card-1", rating: 2 as const, idempotencyKey: "rate-1" },
    ];
    expect(completedNodeAction(actions, "artifact-1", "save-artifact")).toBe(true);
    expect(completedNodeAction(actions, "artifact-2", "save-artifact")).toBe(false);
    expect([...reviewedDeckCardIds(actions, "deck-1")]).toEqual(["card-1"]);
  });
});

