			const state = await this.getLearnerState();
			await mutator(state);
			state.sessionsCount = state.sessions.length;
			await this.saveLearnerState(state);
			updated = state;
		});
		this.learnerStateWriteQueue = run.catch(() => {});
		await run;
		return updated ?? this.getLearnerState();
	}

