  "generatedAt", "sessions", "artifacts", "goals", "questionChecks", "quizResults", "decks", "cardReviews", "feedbackEvents", "usageEvents", "topicEvidence", "learnerProfile",
]);
const MAX_PORTABLE_RECORDS = 10_000;
const SECRET_VALUE_PATTERNS = [
  /-----BEGIN(?: [A-Z]+)* PRIVATE KEY-----/i,
  /\b(?:Bearer|DPoP)\s+[A-Za-z0-9._~+/=-]{16,}\b/i,
  /\b(?:sk|pk|rk|ghp|github_pat|xox[bap])-?[A-Za-z0-9_-]{16,}\b/i,
  /\bAIza[A-Za-z0-9_-]{20,}\b/,
  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/,
] as const;

function normalizedKey(key: string): string {
  return key.replace(/[^a-z0-9]/gi, "").toLowerCase();
}

/** Token counts are data, not credentials, but only under the closed usage-report shape. */
function isAllowedUsageAccountingKey(path: string, key: string): boolean {
  return (key === "inputTokens" || key === "outputTokens" || key === "totalTokens")
    && /^(?:payload|envelope\.payload)\.usageEvents\[\d+\]\.providerReported$/.test(path);
}

/** Reject secrets and local workspace bytes even when nested in arbitrary metadata. */
export function assertPortableDataSafe(value: unknown, path = "payload"): void {
  if (typeof value === "string") {
    if (SECRET_VALUE_PATTERNS.some((pattern) => pattern.test(value))) {
      throw new ContractValidationError(`Portable data contains credential-like text at ${path}.`);
    }
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((entry, index) => assertPortableDataSafe(entry, `${path}[${index}]`));
    return;
  }
  if (!value || typeof value !== "object") return;
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string") {
      throw new ContractValidationError(`Portable data may not contain non-string keys at ${path}.`);
    }
    const entry = (value as Record<string, unknown>)[key];
    const normalized = normalizedKey(key);
    if (!isAllowedUsageAccountingKey(path, key)
      && FORBIDDEN_PORTABLE_KEY_PARTS.some((part) => normalized.includes(part))) {
      throw new ContractValidationError(`Portable data may not contain ${key} at ${path}.`);
    }
    assertPortableDataSafe(entry, `${path}.${key}`);
  }
}

export function validatePortableLearnerData(value: unknown): value is PortableLearnerData {
  if (!hasOnlyKeys(value, PORTABLE_DATA_KEYS)) return false;
  const data = value as Partial<PortableLearnerData>;
  const shapeIsValid = isContractTimestamp(data.generatedAt)
    && isBoundedArray(data.sessions, MAX_PORTABLE_RECORDS)
    && data.sessions.every(validateLearnerSession)
    && isBoundedArray(data.artifacts, MAX_PORTABLE_RECORDS) && data.artifacts.every(validateLearnerArtifact)
    && isBoundedArray(data.goals, MAX_PORTABLE_RECORDS) && data.goals.every(validateLearnerGoal)
    && isBoundedArray(data.questionChecks, MAX_PORTABLE_RECORDS) && data.questionChecks.every(validateLearnerQuestionCheck)
    && isBoundedArray(data.quizResults, MAX_PORTABLE_RECORDS) && data.quizResults.every(validateLearnerQuizResult)
    && isBoundedArray(data.decks, MAX_PORTABLE_RECORDS) && data.decks.every(validateFlashcardDeck)
    && isBoundedArray(data.cardReviews, MAX_PORTABLE_RECORDS) && data.cardReviews.every(validateCardReviewRecord)
    && isBoundedArray(data.studyPriorities, MAX_PORTABLE_RECORDS) && data.studyPriorities.every(validateStudyPriorityRecord)
    && isBoundedArray(data.feedbackEvents, MAX_PORTABLE_RECORDS) && data.feedbackEvents.every(validateLearnerFeedbackEvent)
    && isBoundedArray(data.usageEvents, MAX_PORTABLE_RECORDS) && data.usageEvents.every(validateLearnerUsageEvent)
    && isBoundedArray(data.topicEvidence, MAX_PORTABLE_RECORDS) && data.topicEvidence.every(validateTopicEvidence)
    && isBoundedArray(data.benchmarks, MAX_PORTABLE_RECORDS) && data.benchmarks.every(validateBenchmarkHistoryRecord)
    && isBoundedArray(data.evolutions, MAX_PORTABLE_RECORDS) && data.evolutions.every(validateEvolutionHistoryRecord)
    && validateLearnerProfile(data.learnerProfile);
  if (!shapeIsValid) return false;
  const portable = data as PortableLearnerData;

  const sessionsById = new Map(portable.sessions.map((session) => [session.id, session]));
  if (sessionsById.size !== portable.sessions.length) return false;
  for (const session of portable.sessions) {
    if (!session.parentSessionId) continue;
    const parent = sessionsById.get(session.parentSessionId);
    if (!parent || (session.forkedFromMessageId !== undefined
      && !parent.messages.some((message) => message.id === session.forkedFromMessageId))) return false;
    const visited = new Set<string>();
    let cursor: LearnerSession | undefined = session;
    while (cursor?.parentSessionId) {
      if (visited.has(cursor.id)) return false;
      visited.add(cursor.id);
      cursor = sessionsById.get(cursor.parentSessionId);
    }
  }

  if (!hasUniqueIds(portable.artifacts) || !hasUniqueIds(portable.goals)
    || !hasUniqueIds(portable.questionChecks) || !hasUniqueIds(portable.quizResults)
    || !hasUniqueIds(portable.decks) || !hasUniqueIds(portable.cardReviews)
    || !hasUniqueIds(portable.studyPriorities)
    || !hasUniqueIds(portable.feedbackEvents)
    || !hasUniqueIds(portable.usageEvents) || !hasUniqueIds(portable.topicEvidence)
    || !hasUniqueIds(portable.benchmarks) || !hasUniqueIds(portable.evolutions)) return false;
  const attachmentIds = portable.artifacts.flatMap((artifact) => artifact.attachment ? [artifact.attachment.id] : []);
  if (new Set(attachmentIds).size !== attachmentIds.length) return false;

  for (const artifact of portable.artifacts) {
    const source = artifact.sourceSessionId ? sessionsById.get(artifact.sourceSessionId) : undefined;
    if (artifact.sourceSessionId && !source) return false;
    if (artifact.sourceMessageId && (!source || !source.messages.some((message) => message.id === artifact.sourceMessageId))) return false;
  }
  if (portable.questionChecks.some((check) => check.sessionId && !sessionsById.has(check.sessionId))) return false;
  if (portable.quizResults.some((result) => result.sessionId && !sessionsById.has(result.sessionId))) return false;
  if (portable.usageEvents.some((record) => record.sessionId && !sessionsById.has(record.sessionId))) return false;
  if (portable.benchmarks.some((record) => record.sessionId && !sessionsById.has(record.sessionId))) return false;
  if (portable.evolutions.some((record) => record.sessionId && !sessionsById.has(record.sessionId))) return false;
  if (portable.feedbackEvents.some((event) => !sessionsById.get(event.sessionId)?.messages
    .some((message) => message.id === event.messageId))) return false;

  const cardsByDeckId = new Map(portable.decks.map((deck) => [deck.id, new Map(deck.cards.map((card) => [card.id, card]))]));
  const latestCanonicalReviewByCard = new Map<string, CardReviewRecord>();
  const cardReviewsAreValid = portable.cardReviews.every((review) => {
    const cards = cardsByDeckId.get(review.deckId);
    if (!cards?.has(review.cardId) || (review.sessionId && !sessionsById.has(review.sessionId))) return false;
    if (review.legacyScheduleUnknown) return true;
    try {
      if (review.nextDueAt !== dueAtAfterReview(review.createdAt, review.rating, review.appliedIntervalDays)) return false;
    } catch {
      return false;
    }
    const key = `${review.deckId}:${review.cardId}`;
    const current = latestCanonicalReviewByCard.get(key);
    if (!current || compareContractTimestamps(review.createdAt, current.createdAt) > 0
      || (compareContractTimestamps(review.createdAt, current.createdAt) === 0 && codePointCompare(review.id, current.id) > 0)) {
      latestCanonicalReviewByCard.set(key, review);
    }
    return true;
  });
  if (!cardReviewsAreValid) return false;
  for (const [key, review] of latestCanonicalReviewByCard) {
    const [deckId, cardId] = key.split(":", 2);
    const card = deckId && cardId ? cardsByDeckId.get(deckId)?.get(cardId) : undefined;
    if (!card || card.srs.ease !== review.easeAfter || card.srs.intervalDays !== review.appliedIntervalDays
      || card.srs.dueAt !== review.nextDueAt || card.srs.lastReviewedAt !== review.createdAt
      || card.srs.lastRating !== review.rating || card.srs.repetitions !== review.repetitionsAfter
      || card.srs.lapses !== review.lapsesAfter) return false;
  }

  const priorityTargets = new Set<string>();
  const artifactById = new Map(portable.artifacts.map((artifact) => [artifact.id, artifact]));
  for (const priority of portable.studyPriorities) {
    const targetKey = `${priority.targetType}:${priority.targetId}`;
    if (priorityTargets.has(targetKey)) return false;
    priorityTargets.add(targetKey);
    if (priority.targetType === "deck" && !cardsByDeckId.has(priority.targetId)) return false;
    if (priority.targetType === "goal" && !portable.goals.some((goal) => goal.id === priority.targetId)) return false;
    if (priority.targetType === "verification" && artifactById.get(priority.targetId)?.kind !== "verification") return false;
  }

  const artifactsById = artifactById;
  const questionChecksById = new Map(portable.questionChecks.map((check) => [check.id, check]));
  const quizResultsById = new Map(portable.quizResults.map((result) => [result.id, result]));
  const cardReviewsById = new Map(portable.cardReviews.map((review) => [review.id, review]));
  const decksById = new Map(portable.decks.map((deck) => [deck.id, deck]));
  return portable.topicEvidence.every((evidence) => {
    const reference = evidence.reference;
    if (!reference) return evidence.provenance === "learner-declared";
    if (reference.kind === "session") return sessionsById.has(reference.id);
    if (reference.kind === "artifact") return artifactsById.has(reference.id);
    if (reference.kind === "question-check") return questionChecksById.get(reference.id)?.topic === evidence.topic;
    if (reference.kind === "quiz-result") return quizResultsById.get(reference.id)?.topic === evidence.topic;
    const review = cardReviewsById.get(reference.id);
    return !!review && decksById.get(review.deckId)?.topic === evidence.topic;
  });
}

export function createPortableLearnerEnvelope(data: PortableLearnerData): PortableLearnerEnvelope {
  assertPortableDataSafe(data);
  if (!validatePortableLearnerData(data)) {
    throw new ContractValidationError("Portable learner data has an invalid shape.");
  }
  return {
    kind: PORTABLE_LEARNER_DATA_KIND,
    schemaVersion: LEARNER_CONTRACT_VERSION,
    payload: structuredClone(data),
  };
}

function assertPortableEnvelopeShape(value: unknown): asserts value is VersionedEnvelope<unknown> {
  if (!isRecord(value)) throw new ContractValidationError("Contract envelope must be an object.");
  if (!hasOnlyKeys(value, new Set(["kind", "schemaVersion", "payload"]))) {
    throw new ContractValidationError("Contract envelope contains unknown fields.");
  }
  if (value.kind !== PORTABLE_LEARNER_DATA_KIND) {
    throw new ContractValidationError(`Unsupported contract kind: ${String(value.kind)}.`);
  }
  if (!("payload" in value)) throw new ContractValidationError("Contract envelope has no payload.");
}

/**
 * v1 had no portable scheduler fields. Migration preserves the old reviews as
 * explicitly schedule-unknown history and starts cards as due at generatedAt;
 * it never fabricates a historical due date, mastery claim, or review state.

	 * The receipt journal and every affected record share one IndexedDB
	 * transaction, so a retry can never observe a receipt without its effect.
	 */
	async materializeCanonicalOpenUiAction(
		action: UiAction,
		sourceDocument: UiDocument,
		now = new Date().toISOString(),
	): Promise<OpenUiLearnerRecordMaterialization> {
		if (!validateUiDocument(sourceDocument) || !validateUiActionAgainstDocument(action, sourceDocument)) {
			throw new Error("OpenUI action does not apply to its source document.");
		}
		const timestamp = openUiTimestamp(now);
		const target = action.type === "retry" ? null : targetForOpenUiAction(sourceDocument, action.nodeId);
		if (action.type !== "retry" && !target) throw new Error("OpenUI action target is missing from its source document.");

	const stores = [META_STORE];
	switch (action.type) {
		case "submit-answer":
		case "choose-option":
		case "submit-question-group":
		case "complete-quiz": stores.push(STORES.QUESTION_CHECKS); break;
			case "complete-goal-step": stores.push(STORES.GOALS); break;
			case "complete-plan-item":
			case "update-notes":
			case "save-artifact": stores.push(STORES.LESSON_PLANS); break;
		case "rate-card":
		case "complete-deck": stores.push(STORES.DECKS, STORES.CARD_REVIEWS); break;
			case "retry":
			case "open-handoff": break;
		}

		await this.init();
		if (!this.db) throw new Error("Database not initialized");
		const transaction = this.db.transaction(stores, "readwrite");
		const complete = transactionCompletion(transaction);
		let materialization: OpenUiLearnerRecordMaterialization | null = null;

		try {
			const metaStore = transaction.objectStore(META_STORE);
			const journalKey = openUiJournalKey(sourceDocument.id);
			const stored = await requestValue(metaStore.get(journalKey)) as UiActionJournalMetaRecord | undefined;
			const journal = stored === undefined
				? emptyOpenUiJournal(sourceDocument.id)
				: stored.journal;
			if (!validateUiActionJournal(journal) || journal.documentId !== sourceDocument.id) {
				throw new UiActionReplayConflictError("Stored OpenUI action journal is invalid.");
			}
			const replay = receiptForUiAction(journal, action);
			if (replay) {
				if (replay.state !== "completed" || !replay.result) {
					throw new UiActionReplayConflictError("Stored OpenUI action receipt is incomplete.");
				}
				materialization = { receipt: structuredClone(replay), result: structuredClone(replay.result), replayed: true };
			} else {
				const resultingDocument = documentAfterOpenUiAction(sourceDocument, action, now);
				if (action.type === "submit-answer" || action.type === "choose-option") {
					const question = target && actionQuestion(target);
					if (!question) throw new Error("OpenUI question action has no question target.");
					const grade = automaticallyGrade(action, question);
					const check: QuestionCheckRecord = {
						id: stableOpenUiRecordId("question-check", sourceDocument.id, action.idempotencyKey),
						topic: sourceDocument.title?.trim() || question.header?.trim() || `OpenUI ${sourceDocument.id}`,
						question: question.prompt,
						answer: answerText(action, question),
						...grade,
						createdAt: timestamp,
						sessionId: this.currentSessionId ?? undefined,
					};
					await requestValue(transaction.objectStore(STORES.QUESTION_CHECKS).put(check));
				}
				if (action.type === "submit-question-group") {
					if (!target || target.node.type !== "question-group") throw new Error("OpenUI group action has no question group target.");
					const group = target.node;
					const questionById = new Map(group.questions.map((question) => [question.id, question]));
					const checks = action.responses.map((response) => {
						const question = questionById.get(response.questionId);
						if (!question) throw new Error("OpenUI group response targets a missing question.");
						return {
							id: stableOpenUiRecordId("question-check", sourceDocument.id, `${action.idempotencyKey}:${question.id}`),
							topic: group.topic?.trim() || question.header?.trim() || sourceDocument.title?.trim() || `OpenUI ${sourceDocument.id}`,
							question: question.prompt,
							answer: questionGroupResponseText(response, question),
							...automaticallyGradeQuestionGroupResponse(response, question),
							createdAt: timestamp,
							sessionId: this.currentSessionId ?? undefined,
						} satisfies QuestionCheckRecord;
					});
					const questionChecks = transaction.objectStore(STORES.QUESTION_CHECKS);
					for (const check of checks) await requestValue(questionChecks.put(check));
				}
				if (action.type === "complete-quiz") {
					if (!target || target.node.type !== "quiz") throw new Error("OpenUI quiz action has no quiz target.");
					const quiz = target.node;
					const answers = new Map(action.answers.map((answer) => [answer.questionId, answer.answer]));
					const pending = new Set(action.pendingGradeQuestionIds);
					const skipped = new Set(action.skippedQuestionIds);
					const questionChecks = transaction.objectStore(STORES.QUESTION_CHECKS);
					for (const question of quiz.questions) {
						const answer = answers.get(question.id) ?? "";
						const reportedPartialCredit = action.partialCredits[question.id];
						const grade = pending.has(question.id)
							? { grading: "pending" as const }
							: typeof reportedPartialCredit === "number"
								? { grading: "auto" as const, score: Math.max(0, Math.min(1, reportedPartialCredit)) }
								: skipped.has(question.id)
									? { grading: "auto" as const, score: 0 }
									: automaticallyGradeValues(question, [answer]);
						const check: QuestionCheckRecord = {
							id: stableOpenUiRecordId("question-check", sourceDocument.id, `${action.idempotencyKey}:${question.id}`),
							topic: quiz.title.trim() || question.header?.trim() || sourceDocument.title?.trim() || `OpenUI ${sourceDocument.id}`,
							question: question.prompt,
							answer,
							...grade,
							createdAt: timestamp,
							sessionId: this.currentSessionId ?? undefined,
						};
						await requestValue(questionChecks.put(check));
					}
				}
				if (action.type === "complete-goal-step") {
					if (!target || target.node.type !== "goal") throw new Error("OpenUI goal action has no goal target.");
					const id = stableOpenUiRecordId("goal", sourceDocument.id, target.node.id);
					const goalStore = transaction.objectStore(STORES.GOALS);
					const current = await requestValue(goalStore.get(id)) as LearnerGoal | undefined;
					const base: LearnerGoal = current ?? {
						id,
						title: target.node.title,
						description: target.node.description ?? "",
						status: target.node.status,
						steps: target.node.steps.map((step, index) => ({
							id: step.id,
							order: index,
							title: step.title,
							description: "",
							kind: "milestone",
							successCriteria: step.successCriteria ?? [],
							status: step.status,
						})),
						createdAt: timestamp,
						updatedAt: timestamp,
						sessionId: this.currentSessionId ?? undefined,
					};
					const steps = base.steps.map((step) => step.id === action.stepId
						? { ...step, status: "done" as const, completedAt: now }
						: step);
					const goal: LearnerGoal = {
						...base,
						steps,
						status: steps.length > 0 && steps.every((step) => step.status === "done") ? "completed" : base.status === "completed" ? "active" : base.status,
						updatedAt: timestamp,
					};
					await requestValue(goalStore.put(goal));
				}
				if (action.type === "complete-plan-item" || action.type === "update-notes" || action.type === "save-artifact") {
					const planStore = transaction.objectStore(STORES.LESSON_PLANS);
					const projection = openUiLessonPlanProjection(resultingDocument, timestamp, this.currentSessionId);
					const current = await requestValue(planStore.get(projection.id)) as LessonPlan | undefined;
					await requestValue(planStore.put({
						...projection,
						createdAt: current?.createdAt ?? projection.createdAt,
						sessionId: current?.sessionId ?? projection.sessionId,
					}));
				}
				if (action.type === "rate-card") {
					if (!target || target.node.type !== "deck") throw new Error("OpenUI card action has no deck target.");
					const deckStore = transaction.objectStore(STORES.DECKS);
					const deckId = stableOpenUiRecordId("deck", sourceDocument.id, target.node.id);
					const current = await requestValue(deckStore.get(deckId)) as FlashcardDeck | undefined;
					const priorCards = new Map(current?.cards.map((card) => [card.id, card]));
					const cards: Flashcard[] = target.node.cards.map((card: UiDeckCard) => {
						const prior = priorCards.get(card.id);
						return {
							id: card.id,
							front: card.front,
							back: card.back,
							tags: card.tags,
							srs: prior?.srs ?? initialSrsState(timestamp),
							createdAt: prior?.createdAt ?? timestamp,
							updatedAt: prior?.updatedAt ?? timestamp,
						};
					});
					const card = cards.find((candidate) => candidate.id === action.cardId);
					if (!card) throw new Error("OpenUI card target is missing from its deck.");
					const outcome = applyReview(card.srs, action.rating, timestamp);
					const deck: FlashcardDeck = {
						id: deckId,
						topic: target.node.topic,
						slug: `openui-${sourceDocument.id}-${target.node.id}`,
						title: target.node.title,
						cards: cards.map((candidate) => candidate.id === card.id ? { ...candidate, srs: outcome.next, updatedAt: timestamp } : candidate),
						createdAt: current?.createdAt ?? timestamp,
						updatedAt: timestamp,
						sessionId: current?.sessionId ?? this.currentSessionId ?? undefined,
					};
					const review: CardReviewRecord = {
						id: stableOpenUiRecordId("card-review", sourceDocument.id, action.idempotencyKey),
						deckId,
						cardId: card.id,
						topic: deck.topic,
						slug: deck.slug,
						rating: action.rating,
						appliedIntervalDays: outcome.appliedIntervalDays,
						easeAfter: outcome.next.ease,
						previousIntervalDays: card.srs.intervalDays,
						isLapse: outcome.isLapse,
						createdAt: timestamp,
						sessionId: this.currentSessionId ?? undefined,
					};
					await requestValue(deckStore.put(deck));
					await requestValue(transaction.objectStore(STORES.CARD_REVIEWS).put(review));
				}
				if (action.type === "complete-deck") {
					if (!target || target.node.type !== "deck") throw new Error("OpenUI deck completion has no deck target.");
					const sourceDeck = target.node;
					const deckStore = transaction.objectStore(STORES.DECKS);
					const deckId = stableOpenUiRecordId("deck", sourceDocument.id, sourceDeck.id);
					const current = await requestValue(deckStore.get(deckId)) as FlashcardDeck | undefined;
					const priorCards = new Map(current?.cards.map((card) => [card.id, card]));
					const cards = sourceDeck.cards.map((card: UiDeckCard): Flashcard => {
						const prior = priorCards.get(card.id);
						return {
							id: card.id,
							front: card.front,
							back: card.back,
							tags: card.tags,
							srs: prior?.srs ?? initialSrsState(timestamp),
							createdAt: prior?.createdAt ?? timestamp,
							updatedAt: prior?.updatedAt ?? timestamp,
						};
					});
					const reviews: CardReviewRecord[] = action.ratings.map((rating) => {
						const card = cards.find((candidate) => candidate.id === rating.cardId);
						if (!card) throw new Error("OpenUI card target is missing from its deck.");
						const priorSrs = card.srs;
						const nextSrs = reportedDeckReviewState(priorSrs, rating, timestamp);
						card.srs = nextSrs;
						card.updatedAt = timestamp;
						return {
							id: stableOpenUiRecordId("card-review", sourceDocument.id, `${action.idempotencyKey}:${card.id}`),
							deckId,
							cardId: card.id,
							topic: sourceDeck.topic,
							slug: `openui-${sourceDocument.id}-${sourceDeck.id}`,
							rating: rating.rating,
							appliedIntervalDays: rating.appliedIntervalDays,
							easeAfter: rating.easeAfter,
							previousIntervalDays: priorSrs.intervalDays,
							isLapse: rating.rating === 0,
							createdAt: timestamp,
							sessionId: this.currentSessionId ?? undefined,
						};
					});
					const deck: FlashcardDeck = {
						id: deckId,
						topic: sourceDeck.topic,
						slug: `openui-${sourceDocument.id}-${sourceDeck.id}`,
						title: sourceDeck.title,
						cards,
						createdAt: current?.createdAt ?? timestamp,
						updatedAt: timestamp,
						sessionId: current?.sessionId ?? this.currentSessionId ?? undefined,
					};
					await requestValue(deckStore.put(deck));
					const reviewStore = transaction.objectStore(STORES.CARD_REVIEWS);
					for (const review of reviews) await requestValue(reviewStore.put(review));
				}

				const result: UiActionResult = {
					schemaVersion: UI_CONTRACT_VERSION,
					documentId: action.documentId,
					sourceRevision: action.documentRevision,
					actionIdempotencyKey: action.idempotencyKey,
					status: "completed",
					documentLifecycle: resultingDocument.lifecycle,
					resultingDocument,
				};
import {
  compareContractTimestamps,
  hasOnlyKeys,
  isBoundedArray,
  isBoundedString,
  isContractId,
  isContractTimestamp,
  isRecord,
} from "./validation.js";
import { MIN_EASE, type CardSrsState, validateCardSrsState } from "./srs.js";

export type ArtifactKind =
  | "note"
  | "explanation"
  | "study-plan"
  | "lesson-map"
  | "quiz"
  | "deck"
  | "image"
  | "animation"
  | "verification"
  | "document"
  | "other";

export type ArtifactFormat = "markdown" | "mermaid" | "quiz" | "openui" | "image" | "video" | "json" | "text";

export interface LearnerArtifact {
  id: string;
  kind: ArtifactKind;
  format: ArtifactFormat;
  title: string;
  createdAt: string;
  updatedAt: string;
